function freeze(o){if(o&&typeof o==='object'&&!Object.isFrozen(o)){Object.values(o).forEach(freeze);Object.freeze(o);}return o;}freeze(algorithms);
const byId=Object.freeze(Object.fromEntries(algorithms.map(a=>[a.id,a])));
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function search(q='',cat='all'){return algorithms.filter(a=>(cat==='all'||cat===a.category)&&norm([a.title,a.subtitle,a.category,...Object.values(a.nodes).map(n=>n.question)].join(' ')).includes(norm(q).trim()));}
function getStep(id,node){if(!Object.hasOwn(byId,id))return null;const a=byId[id];node=node||a.start;if(Object.hasOwn(a.nodes,node))return {id:node,kind:'question',data:a.nodes[node]};if(Object.hasOwn(a.outcomes,node))return {id:node,kind:'outcome',data:a.outcomes[node]};return null;}
function transition(id,node,index){const s=getStep(id,node);return s?.kind==='question'&&Number.isInteger(index)&&index>=0?s.data.choices[index]?.next||null:null;}
root.KidBumOrthopedicsAlgorithms=Object.freeze({version:'0.10.82',algorithms,byId,search,getStep,transition});
